import { useState } from "react";
import { LlmProviderCard } from "@/features/settings/cards/LlmProviderCard";
import { PlanningAutomationCard } from "@/features/settings/cards/PlanningAutomationCard";
import { ShellSelectorCard } from "@/features/settings/cards/ShellSelectorCard";
import { KitChangeApprovalCard } from "@/features/settings/cards/KitChangeApprovalCard";
import { TunnelSettings } from "@/features/tunnel";
import { MetricsCollectionCard } from "@/features/settings/cards/MetricsCollectionCard";
import { IdleReaperCard } from "@/features/settings/cards/IdleReaperCard";
import { PerfRetentionCard } from "@/features/settings/cards/PerfRetentionCard";
import { StorageCard } from "@/features/settings/cards/StorageCard";
import { SandboxedConsolesCard } from "@/features/settings/cards/SandboxedConsolesCard";
import { LogsInventoryCard } from "@/features/settings/cards/LogsInventoryCard";
import { LogsViewerCard } from "@/features/settings/cards/LogsViewerCard";
import { LogsRetentionCard } from "@/features/settings/cards/LogsRetentionCard";
import { SessionLogCard } from "@/features/settings/cards/SessionLogCard";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { SettingsPageHeader, SettingsSubHeader as Sub } from "@/features/settings/pages/SettingsPageHeader";

export function PlannerPage() {
  const [selectedStream, setSelectedStream] = useState<string | null>(null);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [notice, setNotice] = useState("");

  const flash = (msg: string) => {
    setNotice(msg);
    setTimeout(() => setNotice(""), 6000);
  };

  const getStreamLabel = (stream: string) => {
    if (stream === "app") return "Application log";
    if (stream === "perf") return "Performance logs";
    return `${stream}.log`;
  };

  return (
    <Stack gap={18} style={{ maxWidth: 820 }}>
      <SettingsPageHeader
        title="Planner"
        description="LLM planning providers, autopilot, the session shell, mobile tunnel, performance, and storage."
      />

      <Sub>Providers &amp; automation</Sub>
      <LlmProviderCard />
      <PlanningAutomationCard />

      <Sub>Design</Sub>
      <KitChangeApprovalCard />

      <Sub>Shell</Sub>
      <ShellSelectorCard />

      <Sub>Mobile tunnel</Sub>
      <TunnelSettings />

      <Sub>Performance &amp; memory</Sub>
      <MetricsCollectionCard />
      <IdleReaperCard />
      <PerfRetentionCard />

      <Sub>Storage &amp; logs</Sub>
      <SandboxedConsolesCard />
      <StorageCard />
      <LogsInventoryCard
        selectedStream={selectedStream}
        onViewStream={setSelectedStream}
        flash={flash}
        refreshTrigger={refreshTrigger}
      />

      {notice && (
        <Text as="div" mono size={11} tone="accent" style={{ marginTop: -8, wordBreak: "break-all" }}>
          {notice}
        </Text>
      )}

      {selectedStream && (
        <LogsViewerCard
          stream={selectedStream}
          fileLabel={getStreamLabel(selectedStream)}
          onClose={() => setSelectedStream(null)}
        />
      )}

      <LogsRetentionCard
        onEnforced={() => setRefreshTrigger(prev => prev + 1)}
        flash={flash}
      />

      <Sub>Session drill-down</Sub>
      <SessionLogCard />
    </Stack>
  );
}
